with valid as (select id, customer_id, device, started_at, country, case when browser = 'Chrome' then 1 else 0 end as is_chrome from sessions where started_at >= timestamp '2023-08-11 11:00:00'), with_prev as (select *, lag(started_at) over (partition by device order by started_at, id) as prev_started_at from valid), flagged as (select *, case when prev_started_at is null or started_at > prev_started_at + interval '30' day then 1 else 0 end as new_group_flag from with_prev), islands as (select id, device, started_at, country, is_chrome, sum(new_group_flag) over (partition by device order by started_at, id rows between unbounded preceding and current row) as island_id from flagged) select date_trunc('quarter', started_at) as quarter_start, sum(case when device = 'tablet' then is_chrome else 0 end) as tablet_is_chrome, min(is_chrome) as min_is_chrome, sort_array(collect_set(device)) as device_list, count_if(device = 'desktop') as desktop_events, round(avg(island_id), 2) as avg_island_id, max(island_id) filter (where device = 'tablet') as tablet_max_island_id from islands group by date_trunc('quarter', started_at) order by desktop_events nulls last;
